function isTruthy(value) {
  if (value === undefined || value === null) return false;
  const v = String(value).toLowerCase();
  return ['1', 'true', 'yes', 'y', 'on'].includes(v);
}

const request = $json ?? {};
const headers = (request && typeof request === 'object' && request.headers && typeof request.headers === 'object')
  ? request.headers
  : {};
const body = (request && typeof request === 'object' && request.body && typeof request.body === 'object')
  ? request.body
  : {};

function getHeader(name) {
  const key = String(name || '').toLowerCase();
  if (!key) return undefined;
  if (headers[key] !== undefined) return headers[key];
  const found = Object.keys(headers).find((k) => k.toLowerCase() === key);
  return found ? headers[found] : undefined;
}

function kebab(key) {
  return String(key || '').toLowerCase().replace(/_/g, '-');
}

function overrideEnv(key) {
  const headerValue = getHeader('x-aiops-env-' + kebab(key));
  if (headerValue !== undefined && headerValue !== null && String(headerValue).trim() !== '') {
    return String(headerValue);
  }
  const envFromBody = (body && typeof body.env === 'object' && body.env) ? body.env : null;
  if (envFromBody && envFromBody[key] !== undefined && envFromBody[key] !== null && String(envFromBody[key]).trim() !== '') {
    return String(envFromBody[key]);
  }
  return '';
}

function pickEnv(key, fallback = '') {
  const overridden = overrideEnv(key);
  if (overridden) return overridden;
  const envValue = $env?.[key];
  return (envValue !== undefined && envValue !== null && String(envValue).trim() !== '') ? String(envValue) : String(fallback || '');
}

const required = {
  GITLAB_API_BASE_URL: pickEnv('GITLAB_API_BASE_URL') || pickEnv('N8N_GITLAB_API_BASE_URL') || (pickEnv('GITLAB_BASE_URL') ? `${pickEnv('GITLAB_BASE_URL').replace(/\/+$/, '')}/api/v4` : ''),
  GITLAB_TOKEN: pickEnv('GITLAB_TOKEN') || pickEnv('N8N_GITLAB_TOKEN') || pickEnv('GITLAB_ADMIN_TOKEN'),
  HR_TALENT_GITLAB_PROJECT_PATH: pickEnv('HR_TALENT_GITLAB_PROJECT_PATH') || pickEnv('HR_TALENT_PROJECT_PATH') || pickEnv('HR_TALENT_MANAGEMENT_PROJECT_PATH') || pickEnv('N8N_GITLAB_PROJECT_PATH')
};

const missing = Object.entries(required)
  .filter(([, value]) => !String(value).trim())
  .map(([key]) => key);

const query = (request && typeof request === 'object' && request.query && typeof request.query === 'object') ? request.query : {};
const strict = isTruthy(query.strict ?? body.strict ?? $env.HR_TALENT_TEST_STRICT);
const requireZulip = isTruthy(query.require_zulip ?? body.require_zulip ?? $env.HR_TALENT_TEST_REQUIRE_ZULIP);

if (requireZulip) {
  const zulipRequired = {
    ZULIP_API_BASE_URL: pickEnv('ZULIP_API_BASE_URL') || pickEnv('N8N_ZULIP_API_BASE_URL'),
    ZULIP_BOT_EMAIL: pickEnv('ZULIP_BOT_EMAIL') || pickEnv('ZULIP_EMAIL'),
    ZULIP_BOT_API_KEY: pickEnv('ZULIP_BOT_API_KEY') || pickEnv('ZULIP_API_KEY'),
    HR_TALENT_ZULIP_STREAM: pickEnv('HR_TALENT_ZULIP_STREAM'),
  };
  for (const [k, v] of Object.entries(zulipRequired)) {
    if (!String(v || '').trim()) missing.push(k);
  }
}
const ok = strict ? missing.length === 0 : true;
const status = ok ? 200 : 424;

function redactHeaders(rawHeaders) {
  const out = {};
  for (const [k, v] of Object.entries(rawHeaders || {})) {
    const lk = String(k).toLowerCase();
    if (lk.startsWith('x-aiops-env-')) {
      out[k] = '***';
      continue;
    }
    out[k] = v;
  }
  return out;
}

function redactEnv(rawEnv) {
  const envObj = (rawEnv && typeof rawEnv === 'object' && !Array.isArray(rawEnv)) ? rawEnv : {};
  const out = {};
  for (const [k, v] of Object.entries(envObj)) {
    const lk = String(k).toLowerCase();
    if (lk.includes('token') || lk.includes('api_key') || lk.includes('password') || lk.includes('secret')) {
      out[k] = '***';
      continue;
    }
    out[k] = v;
  }
  return out;
}

const receivedSafe = {
  query,
  body: {
    ...body,
    env: redactEnv(body.env)
  },
  headers: redactHeaders(headers)
};

return [{
  json: {
    ok,
    status_code: status,
    strict,
    missing,
    message: ok ? 'ok' : 'missing required env vars',
    received: receivedSafe
  }
}];
